import{_ as s,o as a,c as i,a2 as t}from"./chunks/framework.Ck6QqhZl.js";const k=JSON.parse('{"title":"Examples - the demo project","description":"","frontmatter":{},"headers":[],"relativePath":"docs/examples.md","filePath":"docs/examples.md"}'),l={name:"docs/examples.md"};function n(d,e,o,h,p,r){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="examples-the-demo-project" tabindex="-1">Examples - the demo project <a class="header-anchor" href="#examples-the-demo-project" aria-label="Permalink to &quot;Examples - the demo project&quot;">​</a></h1><p>The <code>examples/demo-project/</code> folder is a runnable project skeleton: <code>sounds/</code> (foley, impact, rpg packs), <code>soundefs/</code> (the files below), and an empty <code>baked/</code>. Open that folder in Forge (<code>File → Open Project…</code>) and click any <code>.soundef</code> to preview it.</p><p>Each example is chosen to teach one feature. Start at <code>rpg_pickup</code> (simplest) and work down.</p><table tabindex="0"><thead><tr><th>File</th><th>Teaches</th><th>Key features</th></tr></thead><tbody><tr><td><code>rpg_pickup</code></td><td>The minimal shape</td><td>Pure scalars, explicit sources, no glob, no range</td></tr><tr><td><code>sword_hit</code></td><td>The canonical file</td><td>Layers + selection + gain/pitch/offset ranges + reverb</td></tr><tr><td><code>footstep_suite</code></td><td>Compact variants</td><td>Basename glob, randomized probability</td></tr><tr><td><code>spell_woosh</code></td><td>Range + glob everywhere</td><td>Glob per layer, <code>sequence</code> vs <code>random</code> selection</td></tr><tr><td><code>hammer_limited</code></td><td>Taming loud hits</td><td>Hot (positive dB) layers + <code>limiter</code> bus</td></tr><tr><td><code>slap_delay</code></td><td>Echo</td><td><code>delay</code> (time/feedback/mix), ranged delay time</td></tr><tr><td><code>cave_drip</code></td><td>Space and tails</td><td>Randomized <code>reverb</code> decay/damping + <code>delay</code> + <code>limiter</code></td></tr><tr><td><code>explosion_big</code></td><td>Big layered design</td><td>Five layers, deep pitch-down, staggered offsets</td></tr><tr><td><code>chest_open</code></td><td>Object sequence</td><td>Four layers + reverb, chest thud with sweeteners</td></tr><tr><td><code>armor_equip</code></td><td>Cross-pack layering</td><td>Cloth + plates + helmet across packs</td></tr><tr><td><code>impact_heavy</code></td><td>Every field type</td><td><code>sequence</code> selection, all value forms together</td></tr></tbody></table><h2 id="rpg-pickup-start-here" tabindex="-1"><code>rpg_pickup</code> - start here <a class="header-anchor" href="#rpg-pickup-start-here" aria-label="Permalink to &quot;\`rpg_pickup\` - start here&quot;">​</a></h2><p>Pure scalars, explicit sources, one reverb. No <code>randomRange</code>, no glob. This is the smallest useful file - read it first to see the shape without any randomness.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">layers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  cloth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    sources</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">rpg/Audio/cloth1.ogg</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">rpg/Audio/cloth2.ogg</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">rpg/Audio/cloth3.ogg</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    selection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">random</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      avoidRepeat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    gain</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-2dB</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    pitch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">0st</span></span></code></pre></div><p><code>gain: -2dB</code> and <code>pitch: 0st</code> are fixed values; <code>selection.avoidRepeat: 1</code> stops the same cloth sample twice in a row.</p><h2 id="sword-hit-the-canonical-example" tabindex="-1"><code>sword_hit</code> - the canonical example <a class="header-anchor" href="#sword-hit-the-canonical-example" aria-label="Permalink to &quot;\`sword_hit\` - the canonical example&quot;">​</a></h2><p>Three layers (<code>body</code>, <code>metal</code>, <code>sparkle</code>), <code>selection</code> with <code>avoidRepeat</code>, <code>randomRange</code> on gain/pitch/offset, <code>probability</code> on the optional layers, and a scalar reverb. This is the canonical example. The full annotated version is in the <a href="./spec#canonical-sword_hit">Spec</a>.</p><h2 id="footstep-suite-glob-randomized-probability" tabindex="-1"><code>footstep_suite</code> - glob + randomized probability <a class="header-anchor" href="#footstep-suite-glob-randomized-probability" aria-label="Permalink to &quot;\`footstep_suite\` - glob + randomized probability&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">layers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  body</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    sources</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">impact/footstep_wood_00*.ogg</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # basename glob → many variants</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    gain</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                            # bare number → implicit-unit warning, plays as 1dB</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  carpet</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    sources</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">impact/footstep_carpet_00*.ogg</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    probability</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.6</span></span></code></pre></div><p>One glob line stands in for a whole variant set. Note the bare <code>gain: 1</code> deliberately shows the <code>implicit-unit</code> warning - it still plays.</p><h2 id="spell-woosh-glob-ranges-mixed-selection" tabindex="-1"><code>spell_woosh</code> - glob + ranges + mixed selection <a class="header-anchor" href="#spell-woosh-glob-ranges-mixed-selection" aria-label="Permalink to &quot;\`spell_woosh\` - glob + ranges + mixed selection&quot;">​</a></h2><p>Every layer uses a basename glob and ranged params, and it mixes <code>mode: random</code> (charge, crack) with <code>mode: sequence</code> (shimmer). <code>sequence</code> steps through sources in order and consumes no RNG - good for predictable cycling.</p><h2 id="hammer_limited-the-limiter-bus" tabindex="-1"><code>hammer_limited</code> - the limiter bus <a class="header-anchor" href="#hammer_limited-the-limiter-bus" aria-label="Permalink to &quot;\`hammer_limited\` - the limiter bus {#hammer_limited-the-limiter-bus}&quot;">​</a></h2><p>Layers are intentionally <strong>hot</strong> (<code>gain: 3dB</code>, ranges up to <code>+4dB</code>) so the sum would clip. A <code>limiter</code> on the bus keeps the bake clean:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">effects</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  limiter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">randomRange</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-8dB&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-4dB&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    ceiling</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-0.1dB&quot;</span></span></code></pre></div><p>Reach for the limiter when you want punch without a red clip dot. See <a href="./troubleshooting#the-bake-clips-red-dot">Troubleshooting: clipping</a>.</p><h2 id="slap-delay-the-delay-line" tabindex="-1"><code>slap_delay</code> - the delay line <a class="header-anchor" href="#slap-delay-the-delay-line" aria-label="Permalink to &quot;\`slap_delay\` - the delay line&quot;">​</a></h2><p>A woosh + metal hit through a mono <code>delay</code> with ranged time and feedback:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">effects</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  delay</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    time</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">randomRange</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;140ms&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;260ms&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    feedback</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">randomRange</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.25</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.45</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    mix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.28</span></span></code></pre></div><p>Randomizing <code>time</code> wobbles the slap distance per trigger. <code>delay</code> is distinct from a layer&#39;s <code>offset</code> - see the <a href="./faq">FAQ</a>.</p><h2 id="cave-drip-reverb-tails-delay-limiter" tabindex="-1"><code>cave_drip</code> - reverb tails + delay + limiter <a class="header-anchor" href="#cave-drip-reverb-tails-delay-limiter" aria-label="Permalink to &quot;\`cave_drip\` - reverb tails + delay + limiter&quot;">​</a></h2><p>Showcases randomized <code>reverb.decay</code>/<code>damping</code> for a long dark space, plus a wall-slap <code>delay</code> and a bus <code>limiter</code>. Good reference for the full <code>effects</code> block with ranges.</p><h2 id="explosion-big-large-layered-design" tabindex="-1"><code>explosion_big</code> - large layered design <a class="header-anchor" href="#explosion-big-large-layered-design" aria-label="Permalink to &quot;\`explosion_big\` - large layered design&quot;">​</a></h2><p>Five layers (<code>thump</code>, <code>boom</code>, <code>crack</code>, <code>shrapnel</code>, <code>rumble</code>) with staggered offsets and deep pitch-down (down to <code>-24st</code>) for weight. Shows how layer order and offset build a single cinematic event from small impacts.</p><h2 id="impact-heavy-every-field-type" tabindex="-1"><code>impact_heavy</code> - every field type <a class="header-anchor" href="#impact-heavy-every-field-type" aria-label="Permalink to &quot;\`impact_heavy\` - every field type&quot;">​</a></h2><p>The kitchen-sink file: <code>sequence</code> selection, positive and ranged gain, deep pitch ranges, and a full reverb + delay + limiter chain. Use it to see all value forms in one place. Reproduced in the <a href="./spec#kitchen-sink-all-field-types">Spec</a>.</p><h2 id="chest-open-object-sequence" tabindex="-1"><code>chest_open</code> - object sequence <a class="header-anchor" href="#chest-open-object-sequence" aria-label="Permalink to &quot;\`chest_open\` - object sequence&quot;">​</a></h2><p>Four layers (<code>thud</code>, <code>latch</code>, <code>coins</code>, <code>creak</code>) build a chest open from always-on wood thud to rare coin sweetener. Uses only <code>rpg/Audio</code> for a self-contained example with staggered offsets.</p><h2 id="armor-equip-cross-pack-layering" tabindex="-1"><code>armor_equip</code> - cross-pack layering <a class="header-anchor" href="#armor-equip-cross-pack-layering" aria-label="Permalink to &quot;\`armor_equip\` - cross-pack layering&quot;">​</a></h2><p>Cloth rustle + armor plates + helmet across <code>rpg</code> and <code>foley</code> packs. Shows heterogeneous sound packs in one behavior and basename globs for plates/helmet.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./spec">Spec</a> - the reference for every field these files use.</li><li><a href="./getting-started">Getting Started</a> - preview and bake them in Forge.</li><li><a href="./troubleshooting">Troubleshooting</a> - when an example does not resolve or clips.</li></ul>`,35)])])}const g=s(l,[["render",n]]);export{k as __pageData,g as default};
